import * as SQLite from 'expo-sqlite';
import { EventType, Reaction } from './constants';

let db: SQLite.SQLiteDatabase | null = null;

function getDb(): SQLite.SQLiteDatabase {
  if (!db) throw new Error('Database not initialized');
  return db;
}

export async function initDatabase(): Promise<void> {
  db = await SQLite.openDatabaseAsync('lucien.db');

  await db.execAsync(`
    PRAGMA journal_mode = WAL;

    CREATE TABLE IF NOT EXISTS app_settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      started_at INTEGER NOT NULL,
      ended_at INTEGER,
      long_rest_monologue TEXT
    );

    CREATE TABLE IF NOT EXISTS events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      event_type TEXT NOT NULL,
      reaction TEXT,
      surge_result TEXT,
      narrative TEXT NOT NULL DEFAULT '',
      mask_delta INTEGER NOT NULL DEFAULT 0,
      dagger_delta INTEGER NOT NULL DEFAULT 0,
      bottle_delta INTEGER NOT NULL DEFAULT 0,
      wound_delta INTEGER NOT NULL DEFAULT 0,
      mask_after INTEGER NOT NULL DEFAULT 0,
      dagger_after INTEGER NOT NULL DEFAULT 0,
      bottle_after INTEGER NOT NULL DEFAULT 0,
      wound_after INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL,
      FOREIGN KEY (session_id) REFERENCES sessions(id)
    );

    CREATE TABLE IF NOT EXISTS tracker_flavors (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      mask_flavor TEXT NOT NULL DEFAULT '',
      dagger_flavor TEXT NOT NULL DEFAULT '',
      bottle_flavor TEXT NOT NULL DEFAULT '',
      wound_flavor TEXT NOT NULL DEFAULT '',
      mask_val INTEGER NOT NULL DEFAULT 0,
      dagger_val INTEGER NOT NULL DEFAULT 0,
      bottle_val INTEGER NOT NULL DEFAULT 0,
      wound_val INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS severin_clues (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      clue_type TEXT NOT NULL,
      clue_context TEXT NOT NULL,
      tag TEXT NOT NULL,
      narrative TEXT NOT NULL DEFAULT '',
      created_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS mara_moments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      moment_type TEXT NOT NULL,
      trust_direction TEXT NOT NULL,
      raw_fact TEXT NOT NULL DEFAULT '',
      narrative TEXT NOT NULL DEFAULT '',
      created_at INTEGER NOT NULL
    );
  `);
}

// ─── App settings ─────────────────────────────────────────────────────────────
export async function getSetting(key: string): Promise<string | null> {
  const row = await getDb().getFirstAsync<{ value: string }>(
    'SELECT value FROM app_settings WHERE key = ?', [key]
  );
  return row?.value ?? null;
}

export async function setSetting(key: string, value: string): Promise<void> {
  await getDb().runAsync(
    'INSERT OR REPLACE INTO app_settings (key, value) VALUES (?, ?)', [key, value]
  );
}

// ─── Sessions ─────────────────────────────────────────────────────────────────
export interface DbSession {
  id: number;
  started_at: number;
  ended_at: number | null;
  long_rest_monologue: string | null;
}

export async function createSession(): Promise<number> {
  const result = await getDb().runAsync(
    'INSERT INTO sessions (started_at) VALUES (?)', [Date.now()]
  );
  return result.lastInsertRowId;
}

export async function getActiveSession(): Promise<DbSession | null> {
  return getDb().getFirstAsync<DbSession>(
    'SELECT * FROM sessions WHERE ended_at IS NULL ORDER BY started_at DESC LIMIT 1'
  );
}

export async function getOrCreateSession(): Promise<number> {
  const existing = await getActiveSession();
  if (existing) return existing.id;
  return createSession();
}

export async function endSession(id: number, monologue: string): Promise<void> {
  await getDb().runAsync(
    'UPDATE sessions SET ended_at = ?, long_rest_monologue = ? WHERE id = ?',
    [Date.now(), monologue, id]
  );
}

export async function getAllSessions(): Promise<DbSession[]> {
  return getDb().getAllAsync<DbSession>(
    'SELECT * FROM sessions ORDER BY started_at ASC'
  );
}

// ─── Events ───────────────────────────────────────────────────────────────────
export interface DbEvent {
  id: number;
  session_id: number;
  event_type: EventType;
  reaction: Reaction | null;
  surge_result: string | null;
  narrative: string;
  mask_delta: number;
  dagger_delta: number;
  bottle_delta: number;
  wound_delta: number;
  mask_after: number;
  dagger_after: number;
  bottle_after: number;
  wound_after: number;
  created_at: number;
}

export async function insertEvent(params: {
  session_id: number;
  event_type: EventType;
  reaction: Reaction | null;
  surge_result: string | null;
  narrative: string;
  mask_delta: number;
  dagger_delta: number;
  bottle_delta: number;
  wound_delta: number;
  mask_after: number;
  dagger_after: number;
  bottle_after: number;
  wound_after: number;
}): Promise<number> {
  const result = await getDb().runAsync(
    `INSERT INTO events (
      session_id, event_type, reaction, surge_result, narrative,
      mask_delta, dagger_delta, bottle_delta, wound_delta,
      mask_after, dagger_after, bottle_after, wound_after, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      params.session_id, params.event_type, params.reaction, params.surge_result,
      params.narrative, params.mask_delta, params.dagger_delta,
      params.bottle_delta, params.wound_delta, params.mask_after,
      params.dagger_after, params.bottle_after, params.wound_after, Date.now(),
    ]
  );
  return result.lastInsertRowId;
}

export async function getEventsForSession(sessionId: number): Promise<DbEvent[]> {
  return getDb().getAllAsync<DbEvent>(
    'SELECT * FROM events WHERE session_id = ? ORDER BY created_at ASC',
    [sessionId]
  );
}

export async function getLastNEvents(n: number): Promise<DbEvent[]> {
  return getDb().getAllAsync<DbEvent>(
    'SELECT * FROM events ORDER BY created_at DESC LIMIT ?',
    [n]
  );
}

export async function countEventsInSession(sessionId: number): Promise<number> {
  const row = await getDb().getFirstAsync<{ cnt: number }>(
    'SELECT COUNT(*) as cnt FROM events WHERE session_id = ?', [sessionId]
  );
  return row?.cnt ?? 0;
}

