// ─── Full reset ───────────────────────────────────────────────────────────────
export async function fullReset(): Promise<void> {
  const d = getDb();
  await d.execAsync(`
    DELETE FROM events;
    DELETE FROM sessions;
    DELETE FROM tracker_flavors;
    DELETE FROM severin_clues;
    DELETE FROM mara_moments;
    DELETE FROM app_settings WHERE key != 'condition';
  `);
}

// ─── Export helpers ───────────────────────────────────────────────────────────
export async function getSessionExportText(sessionId: number): Promise<string> {
  const events = await getEventsForSession(sessionId);
  const session = await getDb().getFirstAsync<DbSession>(
    'SELECT * FROM sessions WHERE id = ?', [sessionId]
  );
  if (!session) return '';

  const lines: string[] = [
    `LUCIEN — SESSION LOG`,
    `Started: ${new Date(session.started_at).toLocaleString()}`,
    session.ended_at ? `Ended: ${new Date(session.ended_at).toLocaleString()}` : 'Session ongoing',
    '',
    '--- EVENTS ---',
  ];

  for (const e of events) {
    lines.push(`[${new Date(e.created_at).toLocaleTimeString()}] ${e.event_type.replace(/_/g, ' ')}${e.reaction ? ` — ${e.reaction.replace(/_/g, ' ')}` : ''}`);
    lines.push(e.narrative);
    if (e.surge_result) lines.push(`SURGE: ${e.surge_result}`);
    lines.push('');
  }

  if (session.long_rest_monologue) {
    lines.push('--- LONG REST ---');
    lines.push(session.long_rest_monologue);
  }

  return lines.join('\n');
}

export async function getAllDataExportText(): Promise<string> {
  const sessions = await getAllSessions();
  const clues = await getAllSeverinClues();
  const maraThread = await getAllMaraMoments();
  const lines: string[] = ['LUCIEN — FULL EXPORT', ''];

  for (const session of sessions) {
    lines.push(`=== SESSION ${session.id} ===`);
    lines.push(await getSessionExportText(session.id));
    lines.push('');
  }

  if (clues.length > 0) {
    lines.push('=== SEVERIN BOARD ===');
    for (const c of clues) {
      lines.push(`[${c.clue_type}/${c.clue_context}/${c.tag}] ${c.narrative}`);
    }
    lines.push('');
  }

  if (maraThread.length > 0) {
    lines.push('=== MARA THREAD ===');
    for (const m of maraThread) {
      lines.push(`[${m.moment_type}/${m.trust_direction}] ${m.narrative}`);
    }
  }

  return lines.join('\n');
}
