import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  ActivityIndicator,
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, FONTS } from '../lib/constants';
import { useApp } from '../contexts/AppContext';

interface Props {
  visible: boolean;
  onClose: () => void;
}

type Step = 'drank' | 'dreamed' | 'generating' | 'result';

export default function LongRestModal({ visible, onClose }: Props) {
  const { performLongRest } = useApp();
  const [step, setStep] = useState<Step>('drank');
  const [drank, setDrank] = useState<boolean | null>(null);
  const [dreamed, setDreamed] = useState<boolean | null>(null);
  const [monologue, setMonologue] = useState('');

  function reset() {
    setStep('drank');
    setDrank(null);
    setDreamed(null);
    setMonologue('');
  }

  function handleClose() {
    reset();
    onClose();
  }

  async function handleDrankChoice(choice: boolean) {
    setDrank(choice);
    setStep('dreamed');
  }

  async function handleDreamedChoice(choice: boolean) {
    setDreamed(choice);
    setStep('generating');

    const text = await performLongRest(drank ?? false, choice);
    setMonologue(text);
    setStep('result');
  }

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={handleClose}
    >
      <View style={styles.overlay}>
        <View style={styles.panel}>
          {/* Header */}
          <View style={styles.header}>
            <Text style={styles.headerTitle}>LONG REST</Text>
            {step !== 'generating' && (
              <TouchableOpacity onPress={handleClose} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                <Ionicons name="close" size={18} color={COLORS.textFaint} />
              </TouchableOpacity>
            )}
          </View>

          {/* Step: Did he drink? */}
          {step === 'drank' && (
            <View style={styles.questionBlock}>
              <Text style={styles.questionText}>Did he drink tonight?</Text>
              <Text style={styles.questionSub}>
                Honestly.
              </Text>
              <View style={styles.choiceRow}>
                <TouchableOpacity style={[styles.choiceBtn, styles.choiceBtnYes]} onPress={() => handleDrankChoice(true)}>
                  <Text style={styles.choiceBtnText}>Yes</Text>
                </TouchableOpacity>
                <TouchableOpacity style={[styles.choiceBtn, styles.choiceBtnNo]} onPress={() => handleDrankChoice(false)}>
                  <Text style={styles.choiceBtnText}>No</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* Step: Did he dream? */}
          {step === 'dreamed' && (
            <View style={styles.questionBlock}>
              <Text style={styles.questionText}>Did he dream?</Text>
              <Text style={styles.questionSub}>
                {drank ? 'Through all of it.' : 'In the silence.'}
              </Text>
              <View style={styles.choiceRow}>
                <TouchableOpacity style={[styles.choiceBtn, styles.choiceBtnYes]} onPress={() => handleDreamedChoice(true)}>
                  <Text style={styles.choiceBtnText}>Yes</Text>
                </TouchableOpacity>
                <TouchableOpacity style={[styles.choiceBtn, styles.choiceBtnNo]} onPress={() => handleDreamedChoice(false)}>
                  <Text style={styles.choiceBtnText}>No</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* Generating */}
          {step === 'generating' && (
            <View style={styles.generatingBlock}>
              <ActivityIndicator color={COLORS.gold} size="large" />
              <Text style={styles.generatingText}>Morning is coming.</Text>
            </View>
          )}

          {/* Result — morning state */}
          {step === 'result' && (
            <>
              <ScrollView style={styles.monologueScroll} contentContainerStyle={styles.monologueContent}>
                <Text style={styles.monologueText}>{monologue}</Text>
              </ScrollView>
              <View style={styles.resultFooter}>
                <View style={styles.resultMeta}>
                  <Text style={styles.resultMetaText}>
                    {drank ? 'He drank.' : 'He didn\'t drink.'} {dreamed ? 'He dreamed.' : 'No dreams.'}
                  </Text>
                </View>
                <TouchableOpacity style={styles.doneButton} onPress={handleClose} activeOpacity={0.8}>
                  <Text style={styles.doneButtonText}>CLOSE</Text>
                </TouchableOpacity>
              </View>
            </>
          )}
        </View>
      </View>
    </Modal>
  );
}

