import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  ScrollView,
  ActivityIndicator,
  TextInput,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, FONTS, SEVERIN_SOURCE_TYPES } from '../../lib/constants';
import { useApp } from '../../contexts/AppContext';
import { getAllSeverinClues, insertSeverinClue, getSetting, setSetting, DbSeverinClue } from '../../lib/database';
import { generateSeverinClueNarrative, generateSeverinSummary } from '../../lib/api';

const ZERO_STATE = "What he knew before Alaron: she performed the ritual deliberately, she chose him specifically, and she disappeared before he could ask her why. He's been working on that question for a long time. His working theory is that she's still on the island — she left too many loose ends for someone who covers her tracks this carefully. That might be wishful thinking. He doesn't examine it too closely.";

type AddStep = 'source' | 'fact' | 'generating';

export default function SeverinBoard() {
  const { state } = useApp();
  const [clues, setClues] = useState<DbSeverinClue[]>([]);
  const [loading, setLoading] = useState(true);
  const [addOpen, setAddOpen] = useState(false);
  const [addStep, setAddStep] = useState<AddStep>('source');
  const [selectedSource, setSelectedSource] = useState('');
  const [factText, setFactText] = useState('');
  const [summaryText, setSummaryText] = useState(ZERO_STATE);
  const [summaryLoading, setSummaryLoading] = useState(false);

  useEffect(() => {
    loadAll();
  }, []);

  async function loadAll() {
    setLoading(true);
    const all = await getAllSeverinClues();
    setClues(all);
    const saved = await getSetting('severin_summary');
    setSummaryText(saved ?? ZERO_STATE);
    setLoading(false);
  }

  function resetAdd() {
    setAddStep('source');
    setSelectedSource('');
    setFactText('');
  }

  async function handleSubmitFact() {
    if (!factText.trim()) return;
    setAddStep('generating');

    const narrative = await generateSeverinClueNarrative(
      selectedSource, factText.trim(),
      state.mask, state.dagger, state.bottle, state.wound,
      state.currentSessionEvents
    );

    await insertSeverinClue({
      clue_type: selectedSource,
      clue_context: factText.trim(),
      tag: '',
      narrative,
    });

    const updated = await getAllSeverinClues();
    setClues(updated);
    resetAdd();
    setAddOpen(false);

    setSummaryLoading(true);
    try {
      const newSummary = await generateSeverinSummary(
        updated, state.mask, state.dagger, state.bottle, state.wound
      );
      setSummaryText(newSummary);
      await setSetting('severin_summary', newSummary);
    } finally {
      setSummaryLoading(false);
    }
  }

  function getSourceColor(source: string): string {
    switch (source) {
      case 'Confirmed':               return COLORS.gold;
      case 'Experienced':             return '#b09050';
      case 'Contradicts what he knew': return COLORS.red;
      default:                        return COLORS.textDim;
    }
  }

  if (loading) {
    return <View style={styles.loading}><ActivityIndicator color={COLORS.goldDim} /></View>;
  }

  return (
    <View style={styles.container}>
      <ScrollView style={styles.scroll} contentContainerStyle={styles.content}>
        {/* Living summary — always visible */}
        <View style={styles.summaryBlock}>
          <View style={styles.summaryHeader}>
            <Text style={styles.summaryLabel}>WHAT HE BELIEVES</Text>
            {summaryLoading && <ActivityIndicator color={COLORS.goldDim} size="small" />}
          </View>
          <Text style={styles.summaryText}>{summaryText}</Text>
        </View>

        {/* Clue list */}
        {clues.length === 0 ? (
          <View style={styles.empty}>
            <Text style={styles.emptyText}>No clues logged.</Text>
            <Text style={styles.emptySub}>She left tracks. He just hasn't found them yet.</Text>
          </View>
        ) : (
          <View style={styles.cluesList}>
            {[...clues].reverse().map(clue => (
              <View key={clue.id} style={styles.clueCard}>
                <Text style={[styles.clueSource, { color: getSourceColor(clue.clue_type) }]}>
                  {clue.clue_type.toUpperCase()}
                </Text>
                <Text style={styles.clueFact}>{clue.clue_context}</Text>
                <Text style={styles.clueNarrative}>{clue.narrative}</Text>
              </View>
            ))}
          </View>
        )}
      </ScrollView>

      <View style={styles.addContainer}>
        <TouchableOpacity style={styles.addButton} onPress={() => setAddOpen(true)} activeOpacity={0.8}>
          <Ionicons name="add" size={16} color={COLORS.background} />
          <Text style={styles.addButtonText}>ADD CLUE</Text>
        </TouchableOpacity>
      </View>

      <Modal
        visible={addOpen}
        transparent
        animationType="slide"
        onRequestClose={() => { resetAdd(); setAddOpen(false); }}
      >
        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        >
          <View style={styles.modalOverlay}>
            <View style={styles.modalPanel}>
              <View style={styles.modalHeader}>
                {addStep === 'fact' && (
                  <TouchableOpacity onPress={() => setAddStep('source')} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                    <Ionicons name="chevron-back" size={18} color={COLORS.textFaint} />
                  </TouchableOpacity>
                )}
                <Text style={styles.modalTitle}>
                  {addStep === 'source' ? 'HOW DOES HE KNOW' : addStep === 'fact' ? 'WHAT WAS LEARNED' : 'WRITING...'}
                </Text>
                {addStep !== 'generating' && (
                  <TouchableOpacity onPress={() => { resetAdd(); setAddOpen(false); }} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                    <Ionicons name="close" size={18} color={COLORS.textFaint} />
                  </TouchableOpacity>
                )}
              </View>

              {addStep === 'generating' && (
                <View style={styles.generatingBlock}>
                  <ActivityIndicator color={COLORS.gold} />
                  <Text style={styles.generatingText}>He's trying to make sense of it.</Text>
                </View>
              )}

              {addStep === 'source' && (
                <View>
                  {SEVERIN_SOURCE_TYPES.map(s => (
                    <TouchableOpacity
                      key={s}
                      style={styles.optionItem}
                      onPress={() => { setSelectedSource(s); setAddStep('fact'); }}
                    >
                      <Text style={[styles.optionText, { color: getSourceColor(s) }]}>{s}</Text>
                    </TouchableOpacity>
                  ))}
                </View>
              )}

              {addStep === 'fact' && (
                <View style={styles.factBlock}>
                  <Text style={styles.sourceSelected}>{selectedSource}</Text>
                  <Text style={styles.factPrompt}>One sentence. The raw fact — what was learned.</Text>
                  <TextInput
                    style={styles.factInput}
                    value={factText}
                    onChangeText={setFactText}
                    placeholder="No context needed. Just what was learned."
                    placeholderTextColor={COLORS.textFaint}
                    multiline
                    autoFocus
                    maxLength={500}
                  />
                  <TouchableOpacity
                    style={[styles.submitBtn, !factText.trim() && styles.submitBtnDisabled]}
                    onPress={handleSubmitFact}
                    disabled={!factText.trim()}
                    activeOpacity={0.8}
                  >
                    <Text style={styles.submitBtnText}>LOG CLUE</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </View>
  );
}

