import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  ActivityIndicator,
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import {
  COLORS, FONTS,
  EVENT_GRID, SUBCATEGORIES, REACTIONS,
  EventType, SubcategoryType, Reaction,
} from '../lib/constants';
import { useApp } from '../contexts/AppContext';
import WildMagicSurge, { rollD100, getSurgeDescription } from './WildMagicSurge';

interface Props {
  visible: boolean;
  onClose: () => void;
}

type Step = 'event' | 'subcategory' | 'reaction' | 'surge_check' | 'surge';

export default function LogMomentFlow({ visible, onClose }: Props) {
  const { logEvent } = useApp();
  const [step, setStep] = useState<Step>('event');
  const [selectedEvent, setSelectedEvent] = useState<EventType | null>(null);
  const [selectedSub, setSelectedSub] = useState<SubcategoryType | null>(null);
  const [selectedReaction, setSelectedReaction] = useState<Reaction | null>(null);
  const [surgeRoll, setSurgeRoll] = useState<number | null>(null);
  const [surgeVisible, setSurgeVisible] = useState(false);
  const [logging, setLogging] = useState(false);

  function reset() {
    setStep('event');
    setSelectedEvent(null);
    setSelectedSub(null);
    setSelectedReaction(null);
    setSurgeRoll(null);
    setSurgeVisible(false);
    setLogging(false);
  }

  function handleClose() {
    reset();
    onClose();
  }

  function handleEventSelect(eventType: EventType) {
    setSelectedEvent(eventType);
    setStep('subcategory');
  }

  function handleSubSelect(sub: SubcategoryType) {
    setSelectedSub(sub);
    setStep('reaction');
  }

  async function handleReactionSelect(reaction: Reaction) {
    if (!selectedEvent || !selectedSub) return;
    setSelectedReaction(reaction);

    if (selectedSub === 'd_wild_surge') {
      setStep('surge_check');
    } else {
      await doLog(selectedEvent, selectedSub, reaction, null);
    }
  }

  async function handleSurgeCheckYes() {
    const roll = rollD100();
    setSurgeRoll(roll);
    setStep('surge');
    setSurgeVisible(true);
  }

  async function handleSurgeCheckNo() {
    if (!selectedEvent || !selectedSub || !selectedReaction) return;
    await doLog(selectedEvent, selectedSub, selectedReaction, null);
  }

  async function doLog(eventType: EventType, subcategory: SubcategoryType, reaction: Reaction, surgeResult: string | null) {
    setLogging(true);
    try {
      await logEvent(eventType, subcategory, reaction, surgeResult ?? undefined);
    } finally {
      setLogging(false);
      handleClose();
    }
  }

  async function handleSurgeAcknowledged() {
    setSurgeVisible(false);
    if (!selectedEvent || !selectedSub || !selectedReaction || surgeRoll == null) {
      handleClose();
      return;
    }
    const desc = getSurgeDescription(surgeRoll);
    await doLog(selectedEvent, selectedSub, selectedReaction, desc);
  }

  function goBack() {
    if (step === 'subcategory') setStep('event');
    else if (step === 'reaction') setStep('subcategory');
    else if (step === 'surge_check') setStep('reaction');
  }

  const stepLabel: Record<Step, string> = {
    event:       'WHAT JUST HAPPENED',
    subcategory: 'MORE SPECIFICALLY',
    reaction:    'HOW DID HE HANDLE IT',
    surge_check: 'WILD SURGE',
    surge:       'WILD MAGIC SURGE',
  };

  const selectedEventItem = EVENT_GRID.find(e => e.type === selectedEvent);
  const subOptions = selectedEvent ? SUBCATEGORIES[selectedEvent] : [];
  const selectedSubLabel = selectedEvent && selectedSub
    ? SUBCATEGORIES[selectedEvent]?.find(s => s.type === selectedSub)?.label ?? ''
    : '';

  return (
    <>
      <Modal
        visible={visible && !surgeVisible}
        transparent
        animationType="slide"
        onRequestClose={handleClose}
      >
        <View style={styles.overlay}>
          <View style={styles.panel}>
            {/* Header */}
            <View style={styles.header}>
              {step !== 'event' && !logging && (
                <TouchableOpacity onPress={goBack} style={styles.backBtn} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                  <Ionicons name="chevron-back" size={18} color={COLORS.textFaint} />
                </TouchableOpacity>
              )}
              <Text style={styles.stepLabel}>{stepLabel[step]}</Text>
              {!logging && (
                <TouchableOpacity onPress={handleClose} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                  <Ionicons name="close" size={18} color={COLORS.textFaint} />
                </TouchableOpacity>
              )}
            </View>

            {/* Breadcrumb */}
            {(step === 'reaction' || step === 'surge_check') && !logging && (
              <View style={styles.breadcrumb}>
                <Text style={styles.breadcrumbText}>
                  {selectedEventItem?.label}
                  {selectedSubLabel ? `  ›  ${selectedSubLabel}` : ''}
                </Text>
              </View>
            )}
            {step === 'subcategory' && !logging && selectedEventItem && (
              <View style={styles.breadcrumb}>
                <Text style={styles.breadcrumbText}>{selectedEventItem.label}</Text>
              </View>
            )}

            {logging && (
              <View style={styles.loadingBlock}>
                <ActivityIndicator color={COLORS.gold} />
                <Text style={styles.loadingText}>Writing the moment...</Text>
              </View>
            )}

            {/* Step 1 — Category grid */}
            {step === 'event' && !logging && (
              <ScrollView style={styles.scrollArea}>
                <View style={styles.eventGrid}>
                  {EVENT_GRID.map(item => (
                    <TouchableOpacity
                      key={item.type}
                      style={styles.eventCell}
                      onPress={() => handleEventSelect(item.type)}
                      activeOpacity={0.7}
                    >
                      <Ionicons name={item.icon as any} size={22} color={COLORS.gold} />
                      <Text style={styles.eventCellLabel}>{item.label}</Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </ScrollView>
            )}

            {/* Step 2 — Subcategory list */}
            {step === 'subcategory' && !logging && (
              <ScrollView style={styles.scrollArea}>
                {subOptions.map(sub => (
                  <TouchableOpacity
                    key={sub.type}
                    style={styles.listItem}
                    onPress={() => handleSubSelect(sub.type)}
                    activeOpacity={0.7}
                  >
                    <Text style={styles.listItemText}>{sub.label}</Text>
                    <Ionicons name="chevron-forward" size={14} color={COLORS.textFaint} />
                  </TouchableOpacity>
                ))}
              </ScrollView>
            )}

            {/* Step 3 — Reaction */}
            {step === 'reaction' && !logging && (
              <ScrollView style={styles.scrollArea} contentContainerStyle={styles.reactionContent}>
                <View style={styles.reactionGrid}>
                  {REACTIONS.map(reaction => (
                    <TouchableOpacity
                      key={reaction.type}
                      style={styles.reactionCell}
                      onPress={() => handleReactionSelect(reaction.type)}
                      activeOpacity={0.7}
                    >
                      <Ionicons name={reaction.icon as any} size={20} color={COLORS.goldDim} />
                      <Text style={styles.reactionLabel}>{reaction.label}</Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </ScrollView>
            )}

            {/* Step 3.5 — Surge check */}
            {step === 'surge_check' && !logging && (
              <View style={styles.surgeCheckBlock}>
                <Text style={styles.surgeCheckQ}>Did a surge happen?</Text>
                <View style={styles.surgeChoiceRow}>
                  <TouchableOpacity style={styles.surgeYes} onPress={handleSurgeCheckYes} activeOpacity={0.8}>
                    <Text style={styles.surgeYesText}>YES — ROLL</Text>
                  </TouchableOpacity>
                  <TouchableOpacity style={styles.surgeNo} onPress={handleSurgeCheckNo} activeOpacity={0.8}>
                    <Text style={styles.surgeNoText}>NO</Text>
                  </TouchableOpacity>
                </View>
              </View>
            )}
          </View>
        </View>
      </Modal>

      <WildMagicSurge
        visible={surgeVisible}
        roll={surgeRoll}
        onClose={handleSurgeAcknowledged}
      />
    </>
  );
}

