import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  ScrollView,
  ActivityIndicator,
  TextInput,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, FONTS, MARA_MOMENT_TYPES } from '../../lib/constants';
import { useApp } from '../../contexts/AppContext';
import { getAllMaraMoments, insertMaraMoment, getSetting, setSetting, DbMaraMoment } from '../../lib/database';
import { generateMaraMomentNarrative, generateMaraSummary } from '../../lib/api';

const ZERO_STATE = "She knows more about him than she should. That happened gradually — he didn't mean to let it — and now she's the one person he can't entirely perform for. She's seen him at his worst and she's still here, which he finds both reassuring and deeply inconvenient.";

function inferTrustDirection(momentType: string): string {
  if (['She helped without asking why', 'I told her something true', 'She came back'].includes(momentType)) {
    return 'Closer';
  }
  if (['I pushed her away'].includes(momentType)) {
    return 'Further';
  }
  return 'Complicated';
}

type AddStep = 'moment' | 'fact' | 'generating';

export default function MaraThread() {
  const { state } = useApp();
  const [moments, setMoments] = useState<DbMaraMoment[]>([]);
  const [loading, setLoading] = useState(true);
  const [addOpen, setAddOpen] = useState(false);
  const [addStep, setAddStep] = useState<AddStep>('moment');
  const [selectedMoment, setSelectedMoment] = useState('');
  const [factText, setFactText] = useState('');
  const [summaryText, setSummaryText] = useState(ZERO_STATE);
  const [summaryLoading, setSummaryLoading] = useState(false);

  useEffect(() => {
    loadAll();
  }, []);

  async function loadAll() {
    setLoading(true);
    const all = await getAllMaraMoments();
    setMoments(all);
    const saved = await getSetting('mara_summary');
    setSummaryText(saved ?? ZERO_STATE);
    setLoading(false);
  }

  function resetAdd() {
    setAddStep('moment');
    setSelectedMoment('');
    setFactText('');
  }

  async function handleSubmitFact() {
    if (!factText.trim()) return;
    setAddStep('generating');

    const trustDirection = inferTrustDirection(selectedMoment);

    const narrative = await generateMaraMomentNarrative(
      selectedMoment, factText.trim(),
      state.mask, state.dagger, state.bottle, state.wound,
      state.currentSessionEvents
    );

    await insertMaraMoment({
      moment_type: selectedMoment,
      trust_direction: trustDirection,
      raw_fact: factText.trim(),
      narrative,
    });

    const updated = await getAllMaraMoments();
    setMoments(updated);
    resetAdd();
    setAddOpen(false);

    setSummaryLoading(true);
    try {
      const newSummary = await generateMaraSummary(
        updated, state.mask, state.dagger, state.bottle, state.wound
      );
      setSummaryText(newSummary);
      await setSetting('mara_summary', newSummary);
    } finally {
      setSummaryLoading(false);
    }
  }

  function getTrustColor(dir: string): string {
    if (dir === 'Closer')      return COLORS.gold;
    if (dir === 'Further')     return COLORS.red;
    return COLORS.textDim;
  }

  if (loading) {
    return <View style={styles.loading}><ActivityIndicator color={COLORS.goldDim} /></View>;
  }

  return (
    <View style={styles.container}>
      <ScrollView style={styles.scroll} contentContainerStyle={styles.content}>
        {/* Living summary */}
        <View style={styles.summaryBlock}>
          <View style={styles.summaryHeader}>
            <Text style={styles.summaryLabel}>WHERE THINGS STAND</Text>
            {summaryLoading && <ActivityIndicator color={COLORS.goldDim} size="small" />}
          </View>
          <Text style={styles.summaryText}>{summaryText}</Text>
        </View>

        {/* Moment list */}
        {moments.length === 0 ? (
          <View style={styles.empty}>
            <Text style={styles.emptyText}>No moments logged.</Text>
            <Text style={styles.emptySub}>She's around. He just hasn't admitted it matters yet.</Text>
          </View>
        ) : (
          <View style={styles.momentsList}>
            {[...moments].reverse().map(m => (
              <View key={m.id} style={styles.momentCard}>
                <Text style={[styles.momentTrust, { color: getTrustColor(m.trust_direction) }]}>
                  {m.trust_direction.toUpperCase()}
                </Text>
                <Text style={styles.momentType}>{m.moment_type}</Text>
                {m.raw_fact ? (
                  <Text style={styles.momentFact}>{m.raw_fact}</Text>
                ) : null}
                <Text style={styles.momentNarrative}>{m.narrative}</Text>
              </View>
            ))}
          </View>
        )}
      </ScrollView>

      <View style={styles.addContainer}>
        <TouchableOpacity style={styles.addButton} onPress={() => setAddOpen(true)} activeOpacity={0.8}>
          <Ionicons name="add" size={16} color={COLORS.background} />
          <Text style={styles.addButtonText}>LOG MOMENT</Text>
        </TouchableOpacity>
      </View>

      <Modal
        visible={addOpen}
        transparent
        animationType="slide"
        onRequestClose={() => { resetAdd(); setAddOpen(false); }}
      >
        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        >
          <View style={styles.modalOverlay}>
            <View style={styles.modalPanel}>
              <View style={styles.modalHeader}>
                {addStep === 'fact' && (
                  <TouchableOpacity onPress={() => setAddStep('moment')} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                    <Ionicons name="chevron-back" size={18} color={COLORS.textFaint} />
                  </TouchableOpacity>
                )}
                <Text style={styles.modalTitle}>
                  {addStep === 'moment' ? 'WHAT HAPPENED' : addStep === 'fact' ? 'WHAT ACTUALLY OCCURRED' : 'WRITING...'}
                </Text>
                {addStep !== 'generating' && (
                  <TouchableOpacity onPress={() => { resetAdd(); setAddOpen(false); }} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                    <Ionicons name="close" size={18} color={COLORS.textFaint} />
                  </TouchableOpacity>
                )}
              </View>

              {addStep === 'generating' && (
                <View style={styles.generatingBlock}>
                  <ActivityIndicator color={COLORS.gold} />
                  <Text style={styles.generatingText}>She probably saw it before he did.</Text>
                </View>
              )}

              {addStep === 'moment' && (
                <ScrollView>
                  {MARA_MOMENT_TYPES.map(t => (
                    <TouchableOpacity
                      key={t}
                      style={styles.optionItem}
                      onPress={() => { setSelectedMoment(t); setAddStep('fact'); }}
                    >
                      <Text style={styles.optionText}>{t}</Text>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              )}

              {addStep === 'fact' && (
                <View style={styles.factBlock}>
                  <Text style={styles.momentSelected}>{selectedMoment}</Text>
                  <Text style={styles.factPrompt}>One sentence. What actually happened between them.</Text>
                  <TextInput
                    style={styles.factInput}
                    value={factText}
                    onChangeText={setFactText}
                    placeholder="No context needed. Just what happened."
                    placeholderTextColor={COLORS.textFaint}
                    multiline
                    autoFocus
                  />
                  <TouchableOpacity
                    style={[styles.submitBtn, !factText.trim() && styles.submitBtnDisabled]}
                    onPress={handleSubmitFact}
                    disabled={!factText.trim()}
                    activeOpacity={0.8}
                  >
                    <Text style={styles.submitBtnText}>LOG MOMENT</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </View>
  );
}

