import React, {
  createContext,
  useContext,
  useReducer,
  useCallback,
  useEffect,
} from 'react';
import { AppState as RNAppState } from 'react-native';
import {
  TRACKER_DEFAULTS,
  EventType,
  SubcategoryType,
  SUBCATEGORIES,
  Reaction,
  BASE_WEIGHTS,
  SUBCATEGORY_WEIGHTS,
  applyReactionModifier,
  longRestDeltas,
  TrackerDelta,
} from '../lib/constants';
import {
  initDatabase,
  createSession,
  getOrCreateSession,
  getEventsForSession,
  getAllSessions,
  insertEvent,
  saveTrackerFlavors,
  getLatestTrackerFlavor,
  endSession,
  getSetting,
  setSetting,
  DbEvent,
  fullReset,
} from '../lib/database';
import {
  generateEventNarrative,
  generateTrackerFlavors,
  generateLongRestMonologue,
  generateThresholdHeadline,
  generatePlayDirective,
  TrackerFlavors,
} from '../lib/api';

interface ThresholdTrackers {
  mask: number;
  dagger: number;
  bottle: number;
  wound: number;
}

// ─── State types ──────────────────────────────────────────────────────────────
export interface AppState {
  dbReady: boolean;
  // Trackers
  mask: number;
  dagger: number;
  bottle: number;
  wound: number;
  // Flavors
  maskFlavor: string;
  daggerFlavor: string;
  bottleFlavor: string;
  woundFlavor: string;
  // Headlines
  reactiveHeadline: string;
  thresholdHeadline: string | null;
  prevThresholdTrackers: ThresholdTrackers;
  // Permanent play directive — always visible, persisted in SQLite
  playDirective: string;
  // Session
  currentSessionId: number | null;
  currentSessionEvents: DbEvent[];
  // Meta
  debugMode: boolean;
  loading: boolean;
  morningParagraph: string | null;
}

type AppAction =
  | { type: 'DB_READY'; sessionId: number; events: DbEvent[]; flavors: TrackerFlavors; trackers: ThresholdTrackers; morningParagraph: string | null; playDirective: string; thresholdHeadline: string | null }
  | { type: 'ADD_EVENT'; event: DbEvent }
  | { type: 'UPDATE_TRACKERS'; deltas: TrackerDelta }
  | { type: 'SET_FLAVORS'; flavors: TrackerFlavors }
  | { type: 'SET_REACTIVE_HEADLINE'; text: string }
  | { type: 'SET_THRESHOLD_HEADLINE'; text: string; trackers: ThresholdTrackers }
  | { type: 'RESTORE_THRESHOLD_FROM_DB'; text: string | null }
  | { type: 'SET_PLAY_DIRECTIVE'; text: string }
  | { type: 'SET_DEBUG'; value: boolean }
  | { type: 'SET_LOADING'; value: boolean }
  | { type: 'END_SESSION'; newSessionId: number }
  | { type: 'NEW_SESSION'; sessionId: number }
  | { type: 'RESET_TRACKERS' }
  | { type: 'FULL_RESET'; sessionId: number }
  | { type: 'SET_MORNING_PARAGRAPH'; text: string | null };

function clamp(v: number): number {
  return Math.max(0, Math.min(100, Math.round(v)));
}

function initialState(): AppState {
  return {
    dbReady: false,
    mask: TRACKER_DEFAULTS.mask,
    dagger: TRACKER_DEFAULTS.dagger,
    bottle: TRACKER_DEFAULTS.bottle,
    wound: TRACKER_DEFAULTS.wound,
    maskFlavor: '',
    daggerFlavor: '',
    bottleFlavor: '',
    woundFlavor: '',
    reactiveHeadline: '',
    thresholdHeadline: null,
    prevThresholdTrackers: { ...TRACKER_DEFAULTS },
    playDirective: '',
    currentSessionId: null,
    currentSessionEvents: [],
    debugMode: false,
    loading: false,
    morningParagraph: null,
  };
}

function reducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'DB_READY':
      return {
        ...state,
        dbReady: true,
        currentSessionId: action.sessionId,
        currentSessionEvents: action.events,
        maskFlavor: action.flavors.mask,
        daggerFlavor: action.flavors.dagger,
        bottleFlavor: action.flavors.bottle,
        woundFlavor: action.flavors.wound,
        mask: action.trackers.mask,
        dagger: action.trackers.dagger,
        bottle: action.trackers.bottle,
        wound: action.trackers.wound,
        prevThresholdTrackers: { ...action.trackers },
        morningParagraph: action.morningParagraph,
        playDirective: action.playDirective,
        thresholdHeadline: action.thresholdHeadline,
      };

    case 'ADD_EVENT':
      return {
        ...state,
        currentSessionEvents: [...state.currentSessionEvents, action.event],
        mask: action.event.mask_after,
        dagger: action.event.dagger_after,
        bottle: action.event.bottle_after,
        wound: action.event.wound_after,
      };

    case 'UPDATE_TRACKERS':
      return {
        ...state,
        mask: clamp(state.mask + action.deltas.mask),
        dagger: clamp(state.dagger + action.deltas.dagger),
        bottle: clamp(state.bottle + action.deltas.bottle),
        wound: clamp(state.wound + action.deltas.wound),
      };

    case 'SET_FLAVORS':
      return {
        ...state,
        maskFlavor: action.flavors.mask,
        daggerFlavor: action.flavors.dagger,
        bottleFlavor: action.flavors.bottle,
        woundFlavor: action.flavors.wound,
      };

    case 'SET_REACTIVE_HEADLINE':
      return { ...state, reactiveHeadline: action.text };

    case 'SET_THRESHOLD_HEADLINE':
      return {
        ...state,
        thresholdHeadline: action.text || null,
        prevThresholdTrackers: action.trackers,
      };

    case 'RESTORE_THRESHOLD_FROM_DB':
      return { ...state, thresholdHeadline: action.text || null };

    case 'SET_PLAY_DIRECTIVE':
      return { ...state, playDirective: action.text };

    case 'SET_DEBUG':
      return { ...state, debugMode: action.value };

    case 'SET_LOADING':
      return { ...state, loading: action.value };

    case 'END_SESSION':
      return {
        ...state,
        currentSessionId: action.newSessionId,
        currentSessionEvents: [],
        thresholdHeadline: null,
        reactiveHeadline: '',
      };

    case 'NEW_SESSION':
      return {
        ...state,
        currentSessionId: action.sessionId,
        currentSessionEvents: [],
        morningParagraph: null,
        reactiveHeadline: '',
        thresholdHeadline: null,
      };

    case 'SET_MORNING_PARAGRAPH':
      return { ...state, morningParagraph: action.text };

    case 'RESET_TRACKERS':
      return {
        ...state,
        mask: TRACKER_DEFAULTS.mask,
        dagger: TRACKER_DEFAULTS.dagger,
        bottle: TRACKER_DEFAULTS.bottle,
        wound: TRACKER_DEFAULTS.wound,
      };

    case 'FULL_RESET':
      return {
        ...initialState(),
        dbReady: true,
        currentSessionId: action.sessionId,
      };

    default:
      return state;
  }
}

// ─── Context ──────────────────────────────────────────────────────────────────
interface AppContextValue {
  state: AppState;
  logEvent: (eventType: EventType, subcategory: SubcategoryType | null, reaction: Reaction | null, surgeResult?: string) => Promise<void>;
  refreshFlavors: () => Promise<void>;
  performLongRest: (drank: boolean, dreamed: boolean) => Promise<string>;
  startNewSession: () => Promise<void>;
  toggleDebugMode: () => void;
  resetTrackers: () => Promise<void>;
  doFullReset: () => Promise<void>;
}

const AppContext = createContext<AppContextValue | null>(null);

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(reducer, initialState());

  // ─── Initialize ─────────────────────────────────────────────────────────────
  useEffect(() => {
    (async () => {
      await initDatabase();

      const sessionId = await getOrCreateSession();
      const events = await getEventsForSession(sessionId);

      // Load last tracker values from most recent event or use defaults
      const lastEvent = events[events.length - 1];
      const trackers: ThresholdTrackers = lastEvent
        ? { mask: lastEvent.mask_after, dagger: lastEvent.dagger_after, bottle: lastEvent.bottle_after, wound: lastEvent.wound_after }
        : { ...TRACKER_DEFAULTS };

      // Load saved tracker values if no events
      if (!lastEvent) {
        const savedMask   = await getSetting('tracker_mask');
        const savedDagger = await getSetting('tracker_dagger');
        const savedBottle = await getSetting('tracker_bottle');
        const savedWound  = await getSetting('tracker_wound');
        if (savedMask)   trackers.mask   = parseInt(savedMask,   10);
        if (savedDagger) trackers.dagger = parseInt(savedDagger, 10);
        if (savedBottle) trackers.bottle = parseInt(savedBottle, 10);
        if (savedWound)  trackers.wound  = parseInt(savedWound,  10);
      }

      // Load flavors
      const savedFlavor = await getLatestTrackerFlavor();
      const flavors: TrackerFlavors = savedFlavor
        ? { mask: savedFlavor.mask_flavor, dagger: savedFlavor.dagger_flavor, bottle: savedFlavor.bottle_flavor, wound: savedFlavor.wound_flavor }
        : { mask: '', dagger: '', bottle: '', wound: '' };

      // Load morning paragraph from most recently ended long rest session
      const allSessions = await getAllSessions();
      const lastLongRest = [...allSessions].reverse().find(s => s.ended_at !== null && s.long_rest_monologue);
      const morningParagraph = lastLongRest?.long_rest_monologue ?? null;

      // Load persisted play directive and threshold headline
      const savedPlayDirective = (await getSetting('play_directive')) ?? '';
      const savedThresholdHeadline = (await getSetting('threshold_headline')) ?? null;
      const thresholdHeadline = savedThresholdHeadline || null;

      dispatch({ type: 'DB_READY', sessionId, events, flavors, trackers, morningParagraph, playDirective: savedPlayDirective, thresholdHeadline });

      // Generate play directive if none exists yet
      if (!savedPlayDirective) {
        try {
          const directive = await generatePlayDirective(trackers.mask, trackers.dagger, trackers.bottle, trackers.wound, events);
          await setSetting('play_directive', directive);
          dispatch({ type: 'SET_PLAY_DIRECTIVE', text: directive });
        } catch {}
      }
    })();

    // Re-read threshold from SQLite when app returns to foreground (Fix 2)
    const appStateSub = RNAppState.addEventListener('change', async (nextState) => {
      if (nextState === 'active') {
        try {
          const saved = await getSetting('threshold_headline');
          dispatch({ type: 'RESTORE_THRESHOLD_FROM_DB', text: saved || null });
        } catch {}
      }
    });

    return () => appStateSub.remove();
  }, []);

  // ─── Persist tracker values ──────────────────────────────────────────────────
  useEffect(() => {
    if (!state.dbReady) return;
    setSetting('tracker_mask',   String(state.mask));
    setSetting('tracker_dagger', String(state.dagger));
    setSetting('tracker_bottle', String(state.bottle));
    setSetting('tracker_wound',  String(state.wound));
  }, [state.mask, state.dagger, state.bottle, state.wound, state.dbReady]);

  // ─── Log event ───────────────────────────────────────────────────────────────
  const logEvent = useCallback(async (
    eventType: EventType,
    subcategory: SubcategoryType | null,
    reaction: Reaction | null,
    surgeResult?: string
  ) => {
    if (!state.currentSessionId) return;
    dispatch({ type: 'SET_LOADING', value: true });

    // Subcategory label for narrative generation
    const subcategoryLabel = subcategory
      ? (SUBCATEGORIES[eventType]?.find(s => s.type === subcategory)?.label ?? null)
      : null;

    try {
      const base = subcategory
        ? { ...SUBCATEGORY_WEIGHTS[subcategory] }
        : { ...BASE_WEIGHTS[eventType] };
      const finalDelta = reaction
        ? applyReactionModifier(base, reaction)
        : base;

      const newMask   = clamp(state.mask   + finalDelta.mask);
      const newDagger = clamp(state.dagger + finalDelta.dagger);
      const newBottle = clamp(state.bottle + finalDelta.bottle);
      const newWound  = clamp(state.wound  + finalDelta.wound);

      // Check threshold — any tracker moved 20+ from previous threshold baseline
      const THRESHOLD = 20;
      const changedTrackers: string[] = [];
      if (Math.abs(newMask   - state.prevThresholdTrackers.mask)   >= THRESHOLD) changedTrackers.push('the Mask');
      if (Math.abs(newDagger - state.prevThresholdTrackers.dagger) >= THRESHOLD) changedTrackers.push('the Dagger');
      if (Math.abs(newBottle - state.prevThresholdTrackers.bottle) >= THRESHOLD) changedTrackers.push('the Bottle');
      if (Math.abs(newWound  - state.prevThresholdTrackers.wound)  >= THRESHOLD) changedTrackers.push('the Wound');

      const recentEvents = state.currentSessionEvents;

      // Fire both in parallel: narrative + updated tracker flavors
      const [narrative, newFlavors] = await Promise.all([
        generateEventNarrative(eventType, subcategoryLabel, reaction, state.mask, state.dagger, state.bottle, state.wound, recentEvents),
        generateTrackerFlavors(newMask, newDagger, newBottle, newWound, recentEvents),
      ]);

      const eventId = await insertEvent({
        session_id:   state.currentSessionId,
        event_type:   eventType,
        reaction:     reaction,
        surge_result: surgeResult ?? null,
        narrative,
        mask_delta:   finalDelta.mask,
        dagger_delta: finalDelta.dagger,
        bottle_delta: finalDelta.bottle,
        wound_delta:  finalDelta.wound,
        mask_after:   newMask,
        dagger_after: newDagger,
        bottle_after: newBottle,
        wound_after:  newWound,
      });

      const newEvent: DbEvent = {
        id: eventId,
        session_id:   state.currentSessionId,
        event_type:   eventType,
        reaction,
        surge_result: surgeResult ?? null,
        narrative,
        mask_delta:   finalDelta.mask,
        dagger_delta: finalDelta.dagger,
        bottle_delta: finalDelta.bottle,
        wound_delta:  finalDelta.wound,
        mask_after:   newMask,
        dagger_after: newDagger,
        bottle_after: newBottle,
        wound_after:  newWound,
        created_at:   Date.now(),
      };

      await saveTrackerFlavors({
        session_id: state.currentSessionId,
        mask_flavor: newFlavors.mask,
        dagger_flavor: newFlavors.dagger,
        bottle_flavor: newFlavors.bottle,
        wound_flavor: newFlavors.wound,
        mask_val: newMask,
        dagger_val: newDagger,
        bottle_val: newBottle,
        wound_val: newWound,
      });

      dispatch({ type: 'ADD_EVENT', event: newEvent });
      dispatch({ type: 'SET_FLAVORS', flavors: newFlavors });

      // Threshold headline (if triggered) — fire after reactive
      // Generate both threshold description AND a fresh play directive in parallel
      if (changedTrackers.length > 0) {
        const newTrackers = { mask: newMask, dagger: newDagger, bottle: newBottle, wound: newWound };
        const [thresholdText, newDirective] = await Promise.all([
          generateThresholdHeadline(newMask, newDagger, newBottle, newWound, changedTrackers),
          generatePlayDirective(newMask, newDagger, newBottle, newWound, recentEvents),
        ]);
        await setSetting('threshold_headline', thresholdText);
        await setSetting('play_directive', newDirective);
        dispatch({ type: 'SET_THRESHOLD_HEADLINE', text: thresholdText, trackers: newTrackers });
        dispatch({ type: 'SET_PLAY_DIRECTIVE', text: newDirective });
      }
    } finally {
      dispatch({ type: 'SET_LOADING', value: false });
    }
  }, [state]);

  // ─── Refresh flavors ─────────────────────────────────────────────────────────
  const refreshFlavors = useCallback(async () => {
    if (!state.currentSessionId) return;
    dispatch({ type: 'SET_LOADING', value: true });
    try {
      const flavors = await generateTrackerFlavors(
        state.mask, state.dagger, state.bottle, state.wound,
        state.currentSessionEvents
      );
      await saveTrackerFlavors({
        session_id: state.currentSessionId,
        mask_flavor: flavors.mask,
        dagger_flavor: flavors.dagger,
        bottle_flavor: flavors.bottle,
        wound_flavor: flavors.wound,
        mask_val: state.mask,
        dagger_val: state.dagger,
        bottle_val: state.bottle,
        wound_val: state.wound,
      });
      dispatch({ type: 'SET_FLAVORS', flavors });
    } finally {
      dispatch({ type: 'SET_LOADING', value: false });
    }
  }, [state]);

  // ─── Long rest ───────────────────────────────────────────────────────────────
  const performLongRest = useCallback(async (drank: boolean, dreamed: boolean): Promise<string> => {
    if (!state.currentSessionId) return '';
    dispatch({ type: 'SET_LOADING', value: true });

    try {
      const deltas = longRestDeltas(drank, dreamed);
      const newMask   = clamp(state.mask   + deltas.mask);
      const newDagger = clamp(state.dagger + deltas.dagger);
      const newBottle = clamp(state.bottle + deltas.bottle);
      const newWound  = clamp(state.wound  + deltas.wound);

      const [monologue, newPlayDirective] = await Promise.all([
        generateLongRestMonologue(newMask, newDagger, newBottle, newWound, state.currentSessionEvents, drank, dreamed),
        generatePlayDirective(newMask, newDagger, newBottle, newWound, state.currentSessionEvents),
      ]);

      await endSession(state.currentSessionId, monologue);
      const newSessionId = await getOrCreateSession();

      // Persist new tracker values, clear threshold, save new directive
      await setSetting('tracker_mask',        String(newMask));
      await setSetting('tracker_dagger',      String(newDagger));
      await setSetting('tracker_bottle',      String(newBottle));
      await setSetting('tracker_wound',       String(newWound));
      await setSetting('play_directive',      newPlayDirective);
      await setSetting('threshold_headline',  '');

      // Update flavors after long rest
      const flavors = await generateTrackerFlavors(newMask, newDagger, newBottle, newWound, []);
      await saveTrackerFlavors({
        session_id: newSessionId,
        mask_flavor: flavors.mask,
        dagger_flavor: flavors.dagger,
        bottle_flavor: flavors.bottle,
        wound_flavor: flavors.wound,
        mask_val: newMask,
        dagger_val: newDagger,
        bottle_val: newBottle,
        wound_val: newWound,
      });

      dispatch({ type: 'UPDATE_TRACKERS', deltas });
      dispatch({ type: 'SET_FLAVORS', flavors });
      dispatch({ type: 'SET_MORNING_PARAGRAPH', text: monologue });
      dispatch({ type: 'SET_PLAY_DIRECTIVE', text: newPlayDirective });
      dispatch({ type: 'END_SESSION', newSessionId });

      return monologue;
    } finally {
      dispatch({ type: 'SET_LOADING', value: false });
    }
  }, [state]);

  // ─── New session ─────────────────────────────────────────────────────────────
  const startNewSession = useCallback(async () => {
    if (state.currentSessionId) {
      await endSession(state.currentSessionId, '');
    }
    const id = await createSession();
    dispatch({ type: 'NEW_SESSION', sessionId: id });
  }, [state.currentSessionId]);

  // ─── Debug mode ──────────────────────────────────────────────────────────────
  const toggleDebugMode = useCallback(() => {
    dispatch({ type: 'SET_DEBUG', value: !state.debugMode });
  }, [state.debugMode]);

  // ─── Reset trackers ──────────────────────────────────────────────────────────
  const resetTrackers = useCallback(async () => {
    dispatch({ type: 'RESET_TRACKERS' });
    await setSetting('tracker_mask',   String(TRACKER_DEFAULTS.mask));
    await setSetting('tracker_dagger', String(TRACKER_DEFAULTS.dagger));
    await setSetting('tracker_bottle', String(TRACKER_DEFAULTS.bottle));
    await setSetting('tracker_wound',  String(TRACKER_DEFAULTS.wound));
  }, []);

  // ─── Full reset ───────────────────────────────────────────────────────────────
  const doFullReset = useCallback(async () => {
    await fullReset();
    const newId = await createSession();
    dispatch({ type: 'FULL_RESET', sessionId: newId });
    try {
      const directive = await generatePlayDirective(
        TRACKER_DEFAULTS.mask, TRACKER_DEFAULTS.dagger,
        TRACKER_DEFAULTS.bottle, TRACKER_DEFAULTS.wound, []
      );
      await setSetting('play_directive', directive);
      dispatch({ type: 'SET_PLAY_DIRECTIVE', text: directive });
    } catch {}
  }, []);

  return (
    <AppContext.Provider value={{
      state,
      logEvent,
      refreshFlavors,
      performLongRest,
      startNewSession,
      toggleDebugMode,
      resetTrackers,
      doFullReset,
    }}>
      {children}
    </AppContext.Provider>
  );
}

export function useApp(): AppContextValue {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used within AppProvider');
  return ctx;
}
