import * as SecureStore from 'expo-secure-store';
import {
  LUCIEN_SYSTEM_PROMPT,
  buildContextBlock,
  CLAUDE_MODEL,
  CLAUDE_MAX_TOKENS,
  EventType,
  SubcategoryType,
  Reaction,
} from './constants';
import { DbEvent } from './database';

const API_URL = 'https://api.anthropic.com/v1/messages';
const API_KEY_STORE = 'lucien_anthropic_key';

export async function getApiKey(): Promise<string | null> {
  return SecureStore.getItemAsync(API_KEY_STORE);
}

export async function saveApiKey(key: string): Promise<void> {
  await SecureStore.setItemAsync(API_KEY_STORE, key);
}

export async function clearApiKey(): Promise<void> {
  await SecureStore.deleteItemAsync(API_KEY_STORE);
}

async function callClaude(
  userMessage: string,
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEventNarratives: string[]
): Promise<string> {
  const apiKey = await getApiKey();
  if (!apiKey) throw new Error('No API key configured');

  const contextBlock = buildContextBlock(mask, dagger, bottle, wound, recentEventNarratives);
  const fullUserMessage = `${contextBlock}\n\n${userMessage}`;

  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: CLAUDE_MODEL,
      max_tokens: CLAUDE_MAX_TOKENS,
      system: LUCIEN_SYSTEM_PROMPT,
      messages: [{ role: 'user', content: fullUserMessage }],
    }),
  });

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`API error ${response.status}: ${err}`);
  }

  const data = await response.json();
  return (data.content[0]?.text ?? '').trim();
}

function eventsToNarratives(events: DbEvent[]): string[] {
  return events
    .slice(-10)
    .map(e => e.narrative)
    .filter(Boolean);
}

// ─── Event narrative ─────────────────────────────────────────────────────────
export async function generateEventNarrative(
  eventType: EventType,
  subcategoryLabel: string | null,
  reaction: Reaction | null,
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[]
): Promise<string> {
  const eventLabel = subcategoryLabel ?? eventType.replace(/_/g, ' ');
  const reactionLabel = reaction ? reaction.replace(/_/g, ' ') : null;

  const prompt = `ONE sentence for Lucien's session log. Third person. Emotion or physical sensation only — no invented scene, location, or context.

What happened: ${eventLabel}${reactionLabel ? `\nHow he handled it: ${reactionLabel}` : ''}

One sentence. Hard limit.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
  } catch {
    return `He ${eventLabel.toLowerCase()}.`;
  }
}

// ─── Tracker flavors ─────────────────────────────────────────────────────────
export interface TrackerFlavors {
  mask: string;
  dagger: string;
  bottle: string;
  wound: string;
}

export async function generateTrackerFlavors(
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[]
): Promise<TrackerFlavors> {
  const prompt = `Write four tracker flavor lines. Each is a PLAYER INSTRUCTION — tell the player what behavior to bring to the table, not what Lucien looks like or feels internally. These are stage directions. The player reads them and adjusts HOW THEY PLAY HIM.

WRONG (description): "He keeps his palm pressed flat against the hilt even when he's not casting."
WRONG (description): "His eyes are restless, scanning the room for exits."
RIGHT (directive): "Play him like he's already planning the exit — scan exits when entering any room, one hand always drifting toward the dagger."
RIGHT (directive): "Keep him in performance mode even with allies — let the charm slip only when he thinks no one's watching."

Format exactly:
MASK: [one sentence — what to DO with his public persona right now, given current mask integrity]
DAGGER: [one sentence — what to DO or guard against given the current infernal pressure]
BOTTLE: [one sentence — what to DO or avoid given the current appetite state]
WOUND: [one sentence — how to handle closeness with other characters given current wall height]

Player instructions. Active verbs. "Play him...", "Let him...", "Keep him..." openings. Behavioral, not descriptive. One sentence per line. Maximum 20 words per line. Hard limit.`;

  try {
    const text = await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
    const lines: Record<string, string> = {};
    for (const line of text.split('\n')) {
      const m = line.match(/^(MASK|DAGGER|BOTTLE|WOUND):\s*(.+)/i);
      if (m) lines[m[1].toUpperCase()] = m[2].trim();
    }
    return {
      mask:   lines.MASK   ?? 'The performance is intact. For now.',
      dagger: lines.DAGGER ?? 'The whispers are background noise. He\'s learned to tune them out.',
      bottle: lines.BOTTLE ?? 'The appetite is manageable. He is lying to himself about this.',
      wound:  lines.WOUND  ?? 'The walls are up. He built them well.',
    };
  } catch {
    return {
      mask:   'The performance is intact. For now.',
      dagger: 'The whispers are background noise.',
      bottle: 'The appetite is manageable.',
      wound:  'The walls are up.',
    };
  }
}

// ─── Reactive headline ────────────────────────────────────────────────────────
export async function generateReactiveHeadline(
  eventType: EventType,
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[]
): Promise<string> {
  const eventLabel = eventType.replace(/_/g, ' ');

  const prompt = `One sentence, maximum 10 words. How is Lucien right now after ${eventLabel}. Not what happened — how he is. Physical or behavioral. No invented scene. No quotation marks.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
  } catch {
    return 'Still in it. Moving. Don\'t examine it too closely.';
  }
}

// ─── Threshold headline ────────────────────────────────────────────────────────
export async function generateThresholdHeadline(
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  changedTrackers: string[]
): Promise<string> {
  const what = changedTrackers.join(' and ');

  const prompt = `Write 2-3 sentences. Something has meaningfully shifted in Lucien Vale — ${what} has moved significantly. What does this mean for how he should be played right now? This is a director's note: weighted, specific, behavioral. What changed about him. What it means for the next scene. Third person. No invented location or scene.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, []);
  } catch {
    return `Something shifted in ${what}. The way he carries himself in the next scene will show it.`;
  }
}

// ─── Play directive ───────────────────────────────────────────────────────────
export async function generatePlayDirective(
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[]
): Promise<string> {
  const prompt = `Exactly ONE sentence. Maximum 12 words. Always starts with "Play him".

This is a player instruction for how to perform Lucien Vale in the next scene. Imperative. Behavioral. Specific to his current internal state.

WRONG: "The charm still works but costs more than it used to."
WRONG: "He looks relaxed but there's something coiled in how he holds himself."
WRONG: "He's tense, watching exits."
RIGHT: "Play him like the smile is taking effort he doesn't have."
RIGHT: "Play him like he's waiting for the dagger to say something."
RIGHT: "Play him charming but one drink ahead of where he should be."
RIGHT: "Play him like someone who just did something he can't justify."

Single sentence. Starts with "Play him". Twelve words maximum. Hard limit.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
  } catch {
    return "Play him like calm is a performance he's tired of maintaining.";
  }
}

// ─── Wound arc sentence ───────────────────────────────────────────────────────
export async function generateWoundArcSentence(
  sessions: { sessionNum: number; woundStart: number; woundEnd: number }[]
): Promise<string> {
  if (sessions.length < 2) return '';

  const summary = sessions
    .map(s => `Session ${s.sessionNum}: wound ${s.woundStart} → ${s.woundEnd} (${s.woundEnd > s.woundStart ? 'walls up' : s.woundEnd < s.woundStart ? 'opening' : 'flat'})`)
    .join(', ');

  const prompt = `One or two sentences describing how The Wound (Lucien's capacity for connection, his walls) has moved across these sessions. Third person. Observational. Not literary. Not encouraging. What you'd note watching someone across a table over time.

Wound arc: ${summary}

One to two sentences. Hard limit.`;

  try {
    return await callClaude(prompt, 50, 50, 50, sessions[sessions.length - 1].woundEnd, []);
  } catch {
    return '';
  }
}

// ─── Long rest monologue ─────────────────────────────────────────────────────
export async function generateLongRestMonologue(
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[],
  drank: boolean,
  dreamed: boolean,
): Promise<string> {
  const prompt = `Write a "this is how he wakes up" paragraph. Third person. 3-4 sentences. Not a recap — the texture of this specific morning. How he feels entering the new day: what he's carrying, what's sitting unresolved, what he told himself last night that he half-believes.

Did he drink: ${drank ? 'yes' : 'no'}
Did he dream: ${dreamed ? 'yes' : 'no'}${dreamed ? '\n(Something from the dream is still with him — not described, but felt in how he moves)' : '\n(The absence of dreams is its own weight)'}

Grounded in his physical state and his actual emotional state right now. No invented plot or scene. No first person. What he is carrying into this day.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
  } catch {
    return dreamed
      ? 'He slept. The dream is still in him somewhere — not as images but as a feeling he can\'t name. He gets up anyway.'
      : 'No dreams. The night was a blank and he woke into it already tired. He gets up anyway.';
  }
}

// ─── Severin clue narrative ───────────────────────────────────────────────────
