// ─── Severin living summary ───────────────────────────────────────────────────
export async function generateSeverinSummary(
  clues: { clue_type: string; clue_context: string; narrative: string }[],
  mask: number,
  dagger: number,
  bottle: number,
  wound: number
): Promise<string> {
  if (clues.length === 0) {
    return "What he knew before Alaron: she performed the ritual deliberately, she chose him specifically, and she disappeared before he could ask her why. He's been working on that question for a long time. His working theory is that she's still on the island — she left too many loose ends for someone who covers her tracks this carefully. That might be wishful thinking. He doesn't examine it too closely.";
  }

  const clueList = clues
    .map(c => `[${c.clue_type}] "${c.clue_context}" — ${c.narrative}`)
    .join('\n');

  const prompt = `Rewrite what Lucien currently believes about Severin Draik as a single paragraph. Third person. His actual working theory, shaped by everything below. Incorporate all information. Let him be wrong in at least one interesting way — his emotional investment distorting his read. He's loaded about this and probably slightly defensive. Do not invent details beyond what's given.

ZERO STATE — what he knew before any clues:
She performed an infernal ritual using him as a vessel. She chose him deliberately. She disappeared after. He is on Alaron hunting her.

ALL CLUES (in order received):
${clueList}

Write his current understanding as a single tight paragraph. His voice — what he currently believes.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, []);
  } catch {
    return "He's been putting pieces together. Some of it contradicts the rest. He hasn't figured out which parts to throw out yet.";
  }
}

// ─── Mara living summary ──────────────────────────────────────────────────────
export async function generateMaraSummary(
  moments: { moment_type: string; narrative: string }[],
  mask: number,
  dagger: number,
  bottle: number,
  wound: number
): Promise<string> {
  if (moments.length === 0) {
    return "She knows more about him than she should. That happened gradually — he didn't mean to let it — and now she's the one person he can't entirely perform for. She's seen him at his worst and she's still here, which he finds both reassuring and deeply inconvenient.";
  }

  const momentList = moments
    .map(m => `[${m.moment_type}] ${m.narrative}`)
    .join('\n');

  const prompt = `Write a single paragraph representing Lucien's current sense of where things stand with Mara Venn. Third person. His actual felt sense of this relationship — not a list of events, where things are right now. Incorporate all moments below. Honest but probably slightly minimizing. Do not invent scene or context beyond what's given.

ZERO STATE — before any of this:
She's one ally he actually trusts, though he'd phrase it differently. She's seen him at his worst. He listens to her.

ALL MOMENTS (in order):
${momentList}

Write where things stand right now. Single tight paragraph.`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, []);
  } catch {
    return "Things are complicated between them. He's not examining how complicated.";
  }
}

// ─── Prep for next session ────────────────────────────────────────────────────
export async function generatePrepText(
  mask: number,
  dagger: number,
  bottle: number,
  wound: number,
  recentEvents: DbEvent[],
  severinClues: { narrative: string }[],
  maraMoments: { moment_type: string; trust_direction: string }[],
  lastMonologue: string | null
): Promise<string> {
  const cluesSummary = severinClues.length > 0
    ? `SEVERIN CLUES (${severinClues.length} total): ${severinClues.slice(-3).map(c => c.narrative).join(' // ')}`
    : 'No Severin clues logged.';

  const maraStatus = maraMoments.length > 0
    ? `MARA THREAD: Last moment — ${maraMoments[maraMoments.length - 1].moment_type} (${maraMoments[maraMoments.length - 1].trust_direction})`
    : 'No Mara moments logged.';

  const monologueLine = lastMonologue
    ? `LAST LONG REST: ${lastMonologue.slice(0, 200)}${lastMonologue.length > 200 ? '...' : ''}`
    : 'No long rest on record.';

  const prompt = `Write 150-200 words in Lucien's interior voice walking into the next session. This is not a recap. This is his actual headspace right now — what he's thinking about, what he's avoiding, what he told himself last night and half-believes. First person. Slightly unreliable. Reference real logged events and clues by their specifics. His voice: dry, deflecting, occasionally too honest, performing calm he doesn't feel.

${cluesSummary}
${maraStatus}
${monologueLine}`;

  try {
    return await callClaude(prompt, mask, dagger, bottle, wound, eventsToNarratives(recentEvents));
  } catch {
    return "He's back at the table. That's something. Whatever happened last time didn't kill him, which is either encouraging or a data point he's choosing not to examine. Severin is still out there. The dagger is still in his belt. Mara knows where to find him if she needs to. That's the whole situation, more or less. He's got it handled.";
  }
}
