import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Modal,
  ScrollView,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, FONTS } from '../lib/constants';
import { useApp } from '../contexts/AppContext';
import Timeline from '../components/journey/Timeline';
import SeverinBoard from '../components/journey/SeverinBoard';
import MaraThread from '../components/journey/MaraThread';
import {
  getAllSeverinClues,
  getAllMaraMoments,
  getAllSessions,
} from '../lib/database';
import { generatePrepText } from '../lib/api';

type Tab = 'timeline' | 'severin' | 'mara';

export default function JourneyScreen() {
  const { state } = useApp();
  const [activeTab, setActiveTab] = useState<Tab>('timeline');
  const [prepLoading, setPrepLoading] = useState(false);
  const [prepText, setPrepText] = useState<string | null>(null);

  async function handlePrepMe() {
    setPrepLoading(true);
    try {
      const [clues, maraMoments, sessions] = await Promise.all([
        getAllSeverinClues(),
        getAllMaraMoments(),
        getAllSessions(),
      ]);

      const lastEndedSession = sessions.filter(s => s.ended_at && s.long_rest_monologue).pop();
      const lastMonologue = lastEndedSession?.long_rest_monologue ?? null;

      const text = await generatePrepText(
        state.mask, state.dagger, state.bottle, state.wound,
        state.currentSessionEvents,
        clues,
        maraMoments,
        lastMonologue
      );
      setPrepText(text || "He's back at the table. That's something. Whatever happened last time didn't kill him, which is either encouraging or a data point he's choosing not to examine. Severin is still out there. The dagger is still in his belt. He's got it handled.");
    } catch {
      setPrepText("He's back at the table. That's something. Whatever happened last time didn't kill him, which is either encouraging or a data point he's choosing not to examine. Severin is still out there. The dagger is still in his belt. He's got it handled.");
    } finally {
      setPrepLoading(false);
    }
  }

  const tabs: { key: Tab; label: string }[] = [
    { key: 'timeline', label: 'TIMELINE' },
    { key: 'severin',  label: 'SEVERIN'  },
    { key: 'mara',     label: 'MARA'     },
  ];

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>JOURNEY</Text>
      </View>

      {/* Tabs */}
      <View style={styles.tabBar}>
        {tabs.map(tab => (
          <TouchableOpacity
            key={tab.key}
            style={[styles.tab, activeTab === tab.key && styles.tabActive]}
            onPress={() => setActiveTab(tab.key)}
          >
            <Text style={[styles.tabText, activeTab === tab.key && styles.tabTextActive]}>
              {tab.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Tab content */}
      <View style={styles.content}>
        {activeTab === 'timeline' && <Timeline />}
        {activeTab === 'severin'  && <SeverinBoard />}
        {activeTab === 'mara'     && <MaraThread />}
      </View>

      {/* Prep button */}
      <View style={styles.prepContainer}>
        <TouchableOpacity
          style={styles.prepButton}
          onPress={handlePrepMe}
          disabled={prepLoading}
          activeOpacity={0.8}
        >
          {prepLoading
            ? <ActivityIndicator color={COLORS.background} size="small" />
            : <Text style={styles.prepButtonText}>PREP ME FOR NEXT SESSION</Text>
          }
        </TouchableOpacity>
      </View>

      {/* Full-screen prep modal */}
      <Modal
        visible={!!prepText}
        transparent
        animationType="fade"
        onRequestClose={() => setPrepText(null)}
      >
        <View style={styles.prepOverlay}>
          <View style={styles.prepModal}>
            {/* Modal header */}
            <View style={styles.prepModalHeader}>
              <Text style={styles.prepModalTitle}>WALKING IN</Text>
              <TouchableOpacity
                onPress={() => setPrepText(null)}
                hitSlop={{ top: 12, right: 12, bottom: 12, left: 12 }}
              >
                <Ionicons name="close" size={20} color={COLORS.textFaint} />
              </TouchableOpacity>
            </View>

            {/* Scrollable content */}
            <ScrollView
              style={styles.prepScroll}
              contentContainerStyle={styles.prepScrollContent}
              showsVerticalScrollIndicator={false}
            >
              <Text style={styles.prepText}>{prepText}</Text>
            </ScrollView>

            {/* Footer close */}
            <TouchableOpacity style={styles.prepCloseBtn} onPress={() => setPrepText(null)} activeOpacity={0.8}>
              <Text style={styles.prepCloseBtnText}>CLOSE</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

