import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  Alert,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { COLORS, FONTS } from '../lib/constants';
import { useApp } from '../contexts/AppContext';
import { DbEvent } from '../lib/database';
import LongRestModal from '../components/LongRestModal';

export default function SessionScreen() {
  const { state, startNewSession } = useApp();
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [longRestOpen, setLongRestOpen] = useState(false);

  // Chronological order (oldest first) for session log
  const events = [...state.currentSessionEvents];

  function handleNewSession() {
    Alert.alert(
      'New Session',
      "Start a new real-world session? This archives the current event log. Trackers stay where they are.",
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'New Session', onPress: () => startNewSession() },
      ]
    );
  }

  function formatTime(ts: number): string {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  }

  function getEventLabel(type: string): string {
    return type.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  function getReactionLabel(reaction: string | null): string {
    if (!reaction) return '';
    return reaction.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  function getTrackerChangeSummary(event: DbEvent): string {
    const changes: string[] = [];
    if (event.mask_delta !== 0)   changes.push(`Mask ${event.mask_delta > 0 ? '+' : ''}${event.mask_delta}`);
    if (event.dagger_delta !== 0) changes.push(`Dagger ${event.dagger_delta > 0 ? '+' : ''}${event.dagger_delta}`);
    if (event.bottle_delta !== 0) changes.push(`Bottle ${event.bottle_delta > 0 ? '+' : ''}${event.bottle_delta}`);
    if (event.wound_delta !== 0)  changes.push(`Wound ${event.wound_delta > 0 ? '+' : ''}${event.wound_delta}`);
    return changes.join('  ·  ');
  }

  return (
    <SafeAreaView style={styles.safe}>
      {/* Header — fixed */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>SESSION</Text>
        <TouchableOpacity
          onPress={handleNewSession}
          style={styles.newSessionBtn}
          hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}
        >
          <Text style={styles.newSessionText}>NEW SESSION</Text>
        </TouchableOpacity>
      </View>

      {/* Single ScrollView — all content scrolls together */}
      <ScrollView
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* Waking text — morning paragraph from last long rest */}
        {state.morningParagraph && (
          <View style={styles.morningBlock}>
            <Text style={styles.morningLabel}>WAKING INTO THIS DAY</Text>
            <Text style={styles.morningText}>{state.morningParagraph}</Text>
          </View>
        )}

        {/* Shift block — threshold headline if crossed this session */}
        {state.thresholdHeadline && (
          <View style={styles.shiftBlock}>
            <Text style={styles.shiftLabel}>SHIFT</Text>
            <Text style={styles.shiftText}>{state.thresholdHeadline}</Text>
          </View>
        )}

        {/* Event log — chronological */}
        {events.length === 0 ? (
          <View style={styles.emptyState}>
            <Text style={styles.emptyIcon}>◆</Text>
            <Text style={styles.emptyText}>Nothing logged yet this session.</Text>
            <Text style={styles.emptySubtext}>The night is still young. Unfortunately.</Text>
          </View>
        ) : (
          <View style={styles.eventList}>
            {events.map((item, idx) => {
              const isExpanded = expandedId === item.id;
              return (
                <View key={item.id}>
                  {idx > 0 && <View style={styles.separator} />}
                  <TouchableOpacity
                    style={styles.eventItem}
                    onPress={() => setExpandedId(isExpanded ? null : item.id)}
                    activeOpacity={0.8}
                  >
                    <View style={styles.eventRow}>
                      <Text style={styles.eventTime}>{formatTime(item.created_at)}</Text>
                      <View style={styles.eventMeta}>
                        <Text style={styles.eventType}>{getEventLabel(item.event_type)}</Text>
                        {item.reaction && (
                          <Text style={styles.eventReaction}>{getReactionLabel(item.reaction)}</Text>
                        )}
                      </View>
                      <Ionicons
                        name={isExpanded ? 'chevron-up' : 'chevron-down'}
                        size={14}
                        color={COLORS.textFaint}
                      />
                    </View>

                    <Text style={styles.eventNarrative}>{item.narrative}</Text>

                    {isExpanded && (
                      <View style={styles.eventExpanded}>
                        {item.surge_result && (
                          <View style={styles.surgeResultBlock}>
                            <Text style={styles.surgeLabel}>WILD MAGIC SURGE</Text>
                            <Text style={styles.surgeText}>{item.surge_result}</Text>
                          </View>
                        )}
                        {state.debugMode && (
                          <Text style={styles.debugChanges}>{getTrackerChangeSummary(item)}</Text>
                        )}
                      </View>
                    )}
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        )}
      </ScrollView>

      {/* Long rest button — fixed at bottom */}
      <View style={styles.longRestContainer}>
        <TouchableOpacity
          style={styles.longRestButton}
          onPress={() => setLongRestOpen(true)}
          activeOpacity={0.8}
        >
          <Ionicons name="moon-outline" size={16} color={COLORS.textDim} style={{ marginRight: 8 }} />
          <Text style={styles.longRestText}>LONG REST</Text>
        </TouchableOpacity>
      </View>

      <LongRestModal visible={longRestOpen} onClose={() => setLongRestOpen(false)} />
    </SafeAreaView>
  );
}

