// ─── Reaction amplification ──────────────────────────────────────────────────
export function applyReactionModifier(
  base: TrackerDelta,
  reaction: Reaction
): TrackerDelta {
  const AMPLIFY = 1.2;
  let m = { ...base };

  switch (reaction) {
    case 'enjoyed_more_than_should':
      if (m.mask   < 0) m.mask   = Math.round(m.mask   * AMPLIFY);
      if (m.bottle > 0) m.bottle = Math.round(m.bottle * AMPLIFY);
      if (m.wound  > 0) m.wound  = Math.round(m.wound  * AMPLIFY);
      break;
    case 'hated_himself':
      if (m.mask  < 0) m.mask  = Math.round(m.mask  * AMPLIFY);
      if (m.wound > 0) m.wound = Math.round(m.wound * AMPLIFY);
      break;
    case 'didnt_feel_it':
      if (m.wound > 0) m.wound = Math.round(m.wound * AMPLIFY);
      break;
    case 'scared_himself':
      if (m.dagger > 0) m.dagger = Math.round(m.dagger * AMPLIFY);
      break;
    case 'doesnt_want_to_think':
      if (m.bottle > 0) m.bottle = Math.round(m.bottle * AMPLIFY);
      break;
    case 'owned_it':
    default:
      break;
  }
  return m;
}

// ─── Long rest weights ───────────────────────────────────────────────────────
export function longRestDeltas(drank: boolean, dreamed: boolean): TrackerDelta {
  const base: TrackerDelta = { mask: +8, dagger: 0, bottle: -15, wound: 0 };
  if (drank) {
    base.bottle += 10;
    base.dagger -= 4;
  }
  if (dreamed) {
    base.dagger += 15;
  } else {
    base.dagger += 5;
  }
  return base;
}

