import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  ActivityIndicator,
} from 'react-native';
import { COLORS, FONTS } from '../../lib/constants';
import { getAllSessions, getEventsForSession, getSetting, setSetting, DbSession, DbEvent } from '../../lib/database';
import { generateWoundArcSentence } from '../../lib/api';

interface SessionData {
  session: DbSession;
  events: DbEvent[];
  woundStart: number;
  woundEnd: number;
}

export default function Timeline() {
  const [sessions, setSessions] = useState<SessionData[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [woundArc, setWoundArc] = useState<string | null>(null);

  useEffect(() => {
    loadSessions();
  }, []);

  async function loadSessions() {
    setLoading(true);
    const all = await getAllSessions();
    const result: SessionData[] = [];
    for (const session of all) {
      const events = await getEventsForSession(session.id);
      const woundStart = events.length > 0 ? (events[0].wound_after - events[0].wound_delta) : 70;
      const woundEnd = events.length > 0 ? events[events.length - 1].wound_after : woundStart;
      result.push({ session, events, woundStart, woundEnd });
    }
    setSessions(result);
    setLoading(false);

    if (result.length >= 2) {
      loadWoundArc(result);
    }
  }

  async function loadWoundArc(sessionData: SessionData[]) {
    // Use cached sentence if session count matches
    const cached = await getSetting('wound_arc_sentence');
    const cachedCount = await getSetting('wound_arc_session_count');
    if (cached && cachedCount === String(sessionData.length)) {
      setWoundArc(cached);
      return;
    }

    // Generate new sentence
    const data = sessionData.map((s, i) => ({
      sessionNum: i + 1,
      woundStart: s.woundStart,
      woundEnd: s.woundEnd,
    }));

    try {
      const sentence = await generateWoundArcSentence(data);
      if (sentence) {
        await setSetting('wound_arc_sentence', sentence);
        await setSetting('wound_arc_session_count', String(sessionData.length));
        setWoundArc(sentence);
      }
    } catch {}
  }

  function formatDate(ts: number): string {
    return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
  }

  if (loading) {
    return (
      <View style={styles.loading}>
        <ActivityIndicator color={COLORS.goldDim} />
      </View>
    );
  }

  if (sessions.length === 0) {
    return (
      <View style={styles.empty}>
        <Text style={styles.emptyText}>No sessions yet.</Text>
        <Text style={styles.emptySub}>The journey hasn't started. Or he hasn't admitted it has.</Text>
      </View>
    );
  }

  return (
    <ScrollView style={styles.scroll} contentContainerStyle={styles.content}>
      {/* Wound arc sentence */}
      {woundArc ? (
        <View style={styles.arcBlock}>
          <Text style={styles.arcLabel}>THE WOUND — across time</Text>
          <Text style={styles.arcText}>{woundArc}</Text>
        </View>
      ) : sessions.length >= 2 ? (
        <View style={styles.arcBlock}>
          <Text style={styles.arcLabel}>THE WOUND — across time</Text>
          <Text style={styles.arcPlaceholder}>Tracing the arc...</Text>
        </View>
      ) : null}

      {/* Session list */}
      <View style={styles.sessionList}>
        {[...sessions].reverse().map((s, revIdx) => {
          const sessionNum = sessions.length - revIdx;
          const isExpanded = expandedId === s.session.id;
          const hasLongRest = !!s.session.long_rest_monologue;

          return (
            <View key={s.session.id} style={styles.sessionCard}>
              <TouchableOpacity
                style={styles.sessionHeader}
                onPress={() => setExpandedId(isExpanded ? null : s.session.id)}
                activeOpacity={0.8}
              >
                <View style={styles.sessionMeta}>
                  <Text style={styles.sessionNum}>Session {sessionNum}</Text>
                  <Text style={styles.sessionDate}>{formatDate(s.session.started_at)}</Text>
                </View>
                <View style={styles.sessionStats}>
                  <Text style={styles.sessionStatText}>{s.events.length} events</Text>
                  {hasLongRest && <Text style={styles.sessionRestIcon}>◐</Text>}
                </View>
              </TouchableOpacity>

              {/* Long rest peek when collapsed */}
              {!isExpanded && hasLongRest && (
                <Text style={styles.sessionMonologuePeek} numberOfLines={2}>
                  {s.session.long_rest_monologue}
                </Text>
              )}

              {/* Expanded detail */}
              {isExpanded && (
                <View style={styles.sessionExpanded}>
                  {s.session.long_rest_monologue ? (
                    <View style={styles.monologueBlock}>
                      <Text style={styles.monologueLabel}>LONG REST</Text>
                      <Text style={styles.monologueText}>{s.session.long_rest_monologue}</Text>
                    </View>
                  ) : null}

                  {s.events.length > 0 && (
                    <View style={styles.eventsBlock}>
                      <Text style={styles.eventsLabel}>EVENTS</Text>
                      {s.events.map(e => (
                        <View key={e.id} style={styles.eventRow}>
                          <Text style={styles.eventType}>
                            {e.event_type.replace(/_/g, ' ')}
                          </Text>
                          <Text style={styles.eventNarrative}>{e.narrative}</Text>
                        </View>
                      ))}
                    </View>
                  )}
                </View>
              )}
            </View>
          );
        })}
      </View>
    </ScrollView>
  );
}

