import React, { useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Modal,
  TouchableOpacity,
  Animated,
  ScrollView,
} from 'react-native';
import { COLORS, FONTS, WILD_MAGIC_TABLE, SurgeEntry } from '../lib/constants';

interface Props {
  visible: boolean;
  roll: number | null;
  onClose: () => void;
}

export default function WildMagicSurge({ visible, roll, onClose }: Props) {
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(0.85)).current;

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(fadeAnim, { toValue: 1, duration: 400, useNativeDriver: true }),
        Animated.spring(scaleAnim, { toValue: 1, friction: 6, tension: 60, useNativeDriver: true }),
      ]).start();
    } else {
      fadeAnim.setValue(0);
      scaleAnim.setValue(0.85);
    }
  }, [visible]);

  const entry = roll != null
    ? WILD_MAGIC_TABLE.find(e => roll >= e.low && roll <= e.high) ?? WILD_MAGIC_TABLE[0]
    : null;

  if (!entry || roll == null) return null;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="none"
      onRequestClose={onClose}
    >
      <View style={styles.overlay}>
        <Animated.View style={[styles.container, { opacity: fadeAnim, transform: [{ scale: scaleAnim }] }]}>
          {/* Roll display */}
          <View style={styles.rollBlock}>
            <Text style={styles.rollLabel}>WILD MAGIC SURGE</Text>
            <Text style={styles.rollNumber}>{String(roll).padStart(2, '0')}</Text>
            <View style={styles.rollDivider} />
          </View>

          <ScrollView contentContainerStyle={styles.resultScroll} showsVerticalScrollIndicator={false}>
            {/* Title */}
            <Text style={styles.surgeTitle}>{entry.title}</Text>

            {/* Mechanical */}
            <View style={styles.mechanicalBlock}>
              <Text style={styles.mechanicalLabel}>EFFECT</Text>
              <Text style={styles.mechanicalText}>{entry.mechanical}</Text>
            </View>

            {/* Flavor */}
            <View style={styles.flavorBlock}>
              <Text style={styles.flavorText}>"{entry.flavor}"</Text>
            </View>
          </ScrollView>

          {/* Close */}
          <TouchableOpacity style={styles.closeButton} onPress={onClose} activeOpacity={0.8}>
            <Text style={styles.closeButtonText}>ACKNOWLEDGED</Text>
          </TouchableOpacity>
        </Animated.View>
      </View>
    </Modal>
  );
}

export function rollD100(): number {
  return Math.floor(Math.random() * 100) + 1;
}

export function getSurgeDescription(roll: number): string {
  const entry = WILD_MAGIC_TABLE.find(e => roll >= e.low && roll <= e.high);
  if (!entry) return `Roll ${roll}: Unknown surge.`;
  return `${entry.title} — ${entry.mechanical} "${entry.flavor}"`;
}

