import { useApp } from '../contexts/AppContext';
import ArcaneGlyph from '../components/ArcaneGlyph';
import LogMomentFlow from '../components/LogMomentFlow';
import AdminMenu from '../components/AdminMenu';

// Tracker → glyph state values (mirrors ArcaneGlyph.computeValues)
function dominantCue(
  mask: number, dagger: number, bottle: number, wound: number,
  maskFlavor: string, daggerFlavor: string, bottleFlavor: string, woundFlavor: string,
): string {
  const states = {
    charming:  { score: mask / 100,             text: maskFlavor   },
    volatile:  { score: dagger / 100,            text: daggerFlavor },
    reckless:  { score: bottle / 100,            text: bottleFlavor },
    withdrawn: { score: (100 - mask) / 100,      text: maskFlavor   },
    guarded:   { score: (wound * 0.6 + dagger * 0.4) / 100, text: woundFlavor },
    present:   { score: (100 - wound) / 100,     text: woundFlavor  },
  };
  const top = Object.values(states).reduce((a, b) => b.score > a.score ? b : a);
  return top.text;
}

export default function NowScreen() {
  const { state } = useApp();
  const [logMomentOpen, setLogMomentOpen] = useState(false);
  const [adminOpen, setAdminOpen] = useState(false);
  const [glyphSize, setGlyphSize] = useState(0);

  function onGlyphLayout(e: LayoutChangeEvent) {
    const { width, height } = e.nativeEvent.layout;
    // Square glyph fits the shorter dimension, with a small inset
    setGlyphSize(Math.min(width, height) - 8);
  }

  const cue = dominantCue(
    state.mask, state.dagger, state.bottle, state.wound,
    state.maskFlavor, state.daggerFlavor, state.bottleFlavor, state.woundFlavor,
  );

  return (
    <SafeAreaView style={styles.safe}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>NOW</Text>
        <TouchableOpacity
          onPress={() => setAdminOpen(true)}
          style={styles.gearBtn}
          hitSlop={{ top: 12, right: 12, bottom: 12, left: 12 }}
        >
          <Ionicons name="settings-outline" size={20} color={COLORS.textFaint} />
        </TouchableOpacity>
      </View>

      {/* 1 — PLAY HIM AS */}
      <View style={styles.playBlock}>
        <Text style={styles.playText} numberOfLines={2}>
          {state.playDirective || 'Reading him...'}
        </Text>
        {state.loading && (
          <ActivityIndicator
            color={COLORS.goldDim}
            size="small"
            style={styles.loadingInline}
          />
        )}
      </View>

      {/* 2 — Arcane glyph — takes all remaining space */}
      <View style={styles.glyphContainer} onLayout={onGlyphLayout}>
        {glyphSize > 0 && (
          <ArcaneGlyph
            mask={state.mask}
            dagger={state.dagger}
            bottle={state.bottle}
            wound={state.wound}
            maskFlavor={state.maskFlavor}
            daggerFlavor={state.daggerFlavor}
            bottleFlavor={state.bottleFlavor}
            woundFlavor={state.woundFlavor}
            size={glyphSize}
          />
        )}
      </View>

      {/* 3 — Dominant behavioral cue */}
      <View style={styles.cueBlock}>
        {cue ? (
          <Text style={styles.cueText} numberOfLines={2} ellipsizeMode="tail">{cue}</Text>
        ) : (
          <Text style={styles.cuePlaceholder}>—</Text>
        )}
      </View>

      {/* 4 — LOG MOMENT button */}
      <View style={styles.logButtonContainer}>
        <TouchableOpacity
          style={styles.logButton}
          onPress={() => setLogMomentOpen(true)}
          activeOpacity={0.85}
          disabled={state.loading}
        >
          <Text style={styles.logButtonText}>LOG MOMENT</Text>
          <Ionicons name="add-circle-outline" size={20} color={COLORS.background} style={{ marginLeft: 8 }} />
        </TouchableOpacity>
      </View>

      <LogMomentFlow visible={logMomentOpen} onClose={() => setLogMomentOpen(false)} />
      <AdminMenu visible={adminOpen} onClose={() => setAdminOpen(false)} />
    </SafeAreaView>
  );
}

